-- Eser başına "Neler yapılır?" önerileri.
-- İçerik, Vakıf Katılım Bursa envanter kitaplarından (Cilt 1 ve 2) derlenmiştir; her satırın
-- 'source' alanında kitaptaki cilt/sayfa yazar. İngilizce metinler elle hazırlanmıştır.
-- Güvenli yeniden çalıştırma: tablo varsa oluşturmaz, eski satırları silip yeniden ekler.

create table if not exists public.place_activities (
  id bigint generated by default as identity primary key,
  place_id bigint not null references public.heritage_places(id) on delete cascade,
  kind text not null check (kind in ('gor','kesfet','tat','yap','fotograf','dinlen')),
  title text not null,
  title_en text,
  description text,
  description_en text,
  source text,
  sort_order int not null default 0,
  created_at timestamptz default now()
);

create index if not exists place_activities_place_idx on public.place_activities (place_id, sort_order);

alter table public.place_activities enable row level security;

drop policy if exists "aktiviteler: herkes okuyabilir" on public.place_activities;
create policy "aktiviteler: herkes okuyabilir" on public.place_activities
  for select using (true);
-- Ekleme/silme/güncelleme politikası yok: yalnızca Supabase panelinden (service role) değiştirilir.

delete from public.place_activities;

