insert into public.place_activities (place_id, kind, title, title_en, description, description_en, source, sort_order) values
  (1, 'kesfet', 'Osmanlı''nın ilk hastanesi', 'The first Ottoman hospital', 'Yıldırım Darüşşifası, Osmanlıların ilk hastane yapısı olarak kabul edilir.', 'Yıldırım Hospital is regarded as the first hospital building of the Ottomans.', 'Cilt 2, s. 447', 0),
  (1, 'gor', 'Revaklı avluyu gez', 'Walk the arcaded courtyard', '420 m²''lik revaklı avlunun ortasında fıskiyeli bir şadırvan, çevresinde yirmi oda sıralanır.', 'A fountain stands in the middle of the 420 m² arcaded courtyard, with twenty rooms lined around it.', 'Cilt 2, s. 453', 1),
  (1, 'gor', 'Kubbeli büyük salonu bul', 'Find the domed hall', 'Güneydeki kubbeli salon muayene ve tedavi için ayrılmıştı. İçindeki mihrap, mescit olarak da kullanıldığını düşündürür.', 'The domed hall in the south was used for examination and treatment. Its mihrab suggests it also served as a prayer room.', 'Cilt 2, s. 453', 2),
  (1, 'yap', 'Pencereleri say', 'Count the windows', 'Dış duvarlarda toplam 34 pencere vardır, bir kısmı günümüzde kapatılmıştır.', 'The outer walls have 34 windows in total, some of which are now closed.', 'Cilt 2, s. 453', 3),
  (1, 'kesfet', 'Hekim kadrosunu öğren', 'Meet the medical staff', 'Başlangıçta üç tabip, iki şerbetçi ve iki eczacı görev yapıyordu. Kadro zamanla 27 kişiye ulaştı.', 'It began with three physicians, two sherbet makers and two pharmacists. The staff later grew to 27.', 'Cilt 2, s. 453', 4),
  (2, 'kesfet', 'Adının hikâyesi', 'The story behind the name', 'Kurnaları ördek gagasına benzetildiği için halk arasında ''Ördekli Hamam'' denmiştir.', 'Its basins were likened to duck bills, so people came to call it ''Ördekli Hamam'' (Duck Bath).', 'Cilt 2, s. 151', 0),
  (2, 'kesfet', 'Çifte hamamı keşfet', 'Explore the double bath', 'Kuzeyde kadınlar, güneyde erkekler bölümü yer alır. Osmanlı''nın en büyük çifte hamamlarından biri sayılır.', 'The women''s section lies in the north and the men''s in the south. It is among the largest double baths of the Ottomans.', 'Cilt 2, s. 151-153', 1),
  (2, 'gor', 'Sekiz köşeli havuzu ara', 'Spot the octagonal pool', 'Kadınlar bölümünün soğukluğunda, ortada fıskiyeli sekiz köşeli bir havuz bulunur.', 'In the cooling room of the women''s section, an octagonal pool with a fountain sits in the centre.', 'Cilt 2, s. 153', 2),
  (2, 'gor', 'Büyük kubbeye bak', 'Look up at the great dome', 'Yaklaşık 10,50 m çapındaki kubbenin merkezinde çokgen bir aydınlık feneri vardır.', 'The dome, about 10.5 m across, has a polygonal light lantern at its centre.', 'Cilt 2, s. 153', 3),
  (2, 'yap', 'Kültür merkezine uğra', 'Visit the cultural centre', 'Kitaba göre hamam 2004-2008 arasında restore edilip ''Ördekli Kültür Merkezi'' adıyla kültürel kullanıma açıldı.', 'According to the book, the bath was restored in 2004-2008 and opened for cultural use as the ''Ördekli Cultural Centre''.', 'Cilt 2, s. 153', 4),
  (3, 'kesfet', 'Vakfın hikâyesini oku', 'Read the foundation''s story', 'Dullar Evi Vakfı 1916''da Hacı Saffet Bey tarafından, kimsesiz kadınları korumak için kuruldu.', 'The Widows'' House Foundation was set up in 1916 by Hacı Saffet Bey to protect women in need.', 'Cilt 2, s. 109-111', 0),
  (3, 'gor', 'Odaları say', 'Count the rooms', 'Bahçe içindeki bina, alt ve üst katta 17''şer olmak üzere 34 odadan oluşur.', 'Set in a garden, the building has 34 rooms, 17 on each of its two floors.', 'Cilt 2, s. 109', 1),
  (3, 'kesfet', 'İçindekileri keşfet', 'See what was inside', 'Binada iki salon, hamam, mutfak, bakkal dükkânı, hamurhane ve simit fırını vardı. Dükkânlar vakfın gelirini sağlıyordu.', 'The building had two halls, a bath, a kitchen, a grocery, a dough house and a simit bakery. The shops funded the foundation.', 'Cilt 2, s. 109', 2),
  (3, 'kesfet', 'Özgün adını öğren', 'Learn its original name', 'Yapının özgün adı ''Dul Nisvân-ı Müslimîn''dir.', 'The building''s original name is ''Dul Nisvân-ı Müslimîn''.', 'Cilt 2, s. 111', 3),
  (4, 'kesfet', 'Karabaş lakabının hikâyesi', 'Why ''Karabaş''?', 'Kurucu Yakub Çelebi, siyah Halveti tacı sardığı için ''Karabaş'', uzun boylu olduğu için ''Atvel'' diye anılmıştır.', 'Founder Yakub Çelebi was called ''Karabaş'' for his black Halveti turban and ''Atvel'' for his tall figure.', 'Cilt 2, s. 165', 0),
  (4, 'gor', 'Kalem işlerine yakından bak', 'Study the painted ornaments', 'Kubbede ve çevresinde ahşap üzerine yapılan kalem işleri, döneminin en nitelikli örnekleri arasında sayılır.', 'The pen-work painted on wood in and around the dome is counted among the finest of its era.', 'Cilt 2, s. 165', 1),
  (4, 'gor', 'Semahaneyi gör', 'See the semahane', 'Mevcut semahane, ampir üslubuyla 1822''de inşa edilmiştir.', 'The present semahane was built in the Empire style in 1822.', 'Cilt 2, s. 165', 2),
  (4, 'gor', 'Haziredeki mezar taşını bul', 'Find the gravestone', 'Hazirede yer alan mezar taşına göre dergâhın kurucusu 1550''de vefat etmiştir.', 'According to the gravestone in the cemetery, the founder died in 1550.', 'Cilt 2, s. 165', 3),
  (4, 'yap', 'Geniş bahçede yürü', 'Stroll the large garden', 'Yapılar geniş bir bahçenin içinde konumlanır. Tekke ve semahane 2002-2005 arasında restore edilmiştir.', 'The buildings stand in a large garden. The tekke and semahane were restored in 2002-2005.', 'Cilt 2, s. 165', 4),
  (5, 'gor', 'Avluyu ve odaları gez', 'Explore the courtyard', 'Han, bir avlu çevresinde sıralanmış altlı üstlü odalardan oluşan klasik Osmanlı han planındadır.', 'The han follows the classic Ottoman plan, with two-storey rooms ranged around a courtyard.', 'Cilt 2, s. 17', 0),
  (5, 'kesfet', 'Ahır avlusuna geç', 'Step into the stable court', 'Doğu duvarındaki geçişten kemerlerle çevrili ikinci avluya ulaşılır. Burası Osmanlı''dan kalan nadir ahır yapılarından biridir.', 'A passage in the east wall leads to a second, arcaded courtyard, one of the rare surviving Ottoman stables.', 'Cilt 2, s. 17-21', 1),
  (5, 'gor', 'Köşk mescidi bul', 'Find the kiosk mosque', 'Ahır avlusunun ortasında, bazı Selçuklu kervansaraylarında da görülen müstakil bir mescit vardır.', 'In the middle of the stable court stands a free-standing mosque, as seen in some Seljuk caravanserais.', 'Cilt 2, s. 19', 2),
  (5, 'tat', 'Avluda çay iç', 'Have tea in the courtyard', 'Kitaba göre hanın avlusu çay bahçesi olarak kullanılıyor.', 'According to the book, the han''s courtyard is used as a tea garden.', 'Cilt 2, s. 21', 3),
  (5, 'yap', 'İpek ürünlerine bak', 'Browse the silk goods', 'Kitaba göre üst katta ipek ticareti yapan işletmeler yer alıyor.', 'According to the book, silk traders operate on the upper floor.', 'Cilt 2, s. 21', 4),
  (5, 'kesfet', 'Aynı aksta yürü', 'Walk the same axis', 'Han; Orhan Camii, Emir Hanı ve Ulucami ile aynı aks üzerinde yer alır.', 'The han lies on the same axis as the Orhan Mosque, Emir Han and the Grand Mosque.', 'Cilt 2, s. 17', 5),
  (6, 'kesfet', 'Koza Han''ın kardeşi', 'Koza Han''s sibling', 'Koza Han''dan sonra yaptırılan ikinci büyük handır. Bu yüzden ''Hân-ı Cedîd-i Sânî'' (ikinci yeni han) diye anılmıştır.', 'It is the second great han built after Koza Han, which is why it was called ''Hân-ı Cedîd-i Sânî'' (second new han).', 'Cilt 2, s. 43', 0),
  (6, 'gor', 'Avluyu ölç', 'Take in the courtyard', 'Han yaklaşık 70 × 75 m ölçülerinde ve iki katlıdır. Alt katta sivri kemerli, çapraz tonozlu revaklar sıralanır.', 'The han measures about 70 × 75 m on two floors. The ground floor has pointed arches and cross-vaulted arcades.', 'Cilt 2, s. 45', 1),
  (6, 'gor', 'Ocaklı odalara bak', 'Look at the hearth rooms', 'Üst katta her biri ocaklı kırk sekiz oda bulunur.', 'The upper floor has forty-eight rooms, each with its own hearth.', 'Cilt 2, s. 45', 2),
  (6, 'kesfet', 'Ahır bölümünü tanı', 'Spot the stable wing', 'Batı cephesinin boydan boya beşik tonozla örtülü olması, burasının ahır olarak kullanıldığını gösterir.', 'The barrel vault running the length of the west side shows it was used as a stable.', 'Cilt 2, s. 45', 3),
  (6, 'kesfet', 'İnşa tarihini öğren', 'Learn when it was built', 'Arşiv belgelerine göre inşaat 1507''de başlamış, 1508''de tamamlanmıştır. Mimarı Yâkub Şah''tır.', 'Archive records show construction began in 1507 and ended in 1508. The architect was Yâkub Şah.', 'Cilt 2, s. 43', 4),
  (7, 'kesfet', 'Lonca Hanı''nı öğren', 'Meet the ''Guild Han''', 'İlk yıllarda ''Lonca Hanı'' olarak anılmış, sonra ''Hacı İvaz Paşa Hanı'' ve ''Geyve Hanı'' adlarıyla tanınmıştır.', 'In its first years it was called the ''Guild Han'', later ''Hacı İvaz Paşa Han'' and ''Geyve Han''.', 'Cilt 2, s. 31', 0),
  (7, 'gor', 'Şadırvanlı avluya in', 'Visit the fountain courtyard', 'İki katlı, kare planlı hanın ortasında avlu ve şadırvan vardır. Alt katta 26, üst katta 30 oda bulunur.', 'The square, two-storey han has a courtyard with a fountain. There are 26 rooms below and 30 above.', 'Cilt 2, s. 33', 1),
  (7, 'gor', 'Çapraz tonozlu kemerlere bak', 'Look at the cross vaults', 'Sağlam ayaklara oturan sivri kemerler çapraz tonozla örtülüdür. Duvarlar iki sıra kirpi saçakla biter.', 'Pointed arches on sturdy piers carry cross vaults. The walls end in a double row of sawtooth eaves.', 'Cilt 2, s. 33', 2),
  (7, 'gor', 'Tek kubbeli mescidi bul', 'Find the domed mosque', 'Hanın doğu kısmında, zemin katta tek kubbeli bir mescit yer alır.', 'A single-domed mosque sits on the ground floor in the east part of the han.', 'Cilt 2, s. 33', 3),
  (7, 'kesfet', 'Bedesten''in doğu kapısında dur', 'Stand at the Bedesten''s east gate', 'Han, Bedesten''in doğu kapısı çıkışında, Bursa çarşısının en işlek noktalarından birindedir.', 'The han stands at the Bedesten''s east gate, one of the busiest spots of the Bursa bazaar.', 'Cilt 2, s. 33', 4),
  (8, 'kesfet', 'İlk Osmanlı hamamı', 'The first Ottoman bath', '1340''ta Orhan Bey tarafından yaptırılan hamam, Osmanlı hamam mimarisinin ilk örneklerinden biridir.', 'Built by Orhan Bey in 1340, the bath is one of the earliest examples of Ottoman bath architecture.', 'Cilt 1, s. 207-211', 0),
  (8, 'kesfet', 'Aynalı Çarşı adının hikâyesi', 'How it became ''Aynalı Çarşı''', 'Yapı farklı dönemlerde Bıçakçılar, Hatuniye Hamamı ve Aynalı Çarşı gibi adlarla anılmıştır. 1934''te araştırmalarla hamam olduğu anlaşıldı.', 'It has gone by names such as Bıçakçılar, Hatuniye Bath and Aynalı Çarşı. Research in 1934 confirmed it was a bath.', 'Cilt 1, s. 207-209', 1),
  (8, 'gor', 'Soğukluk kubbesine bak', 'Look up at the cooling-room dome', '11,95 × 11,86 m''lik soğukluk, tromplarla geçilen sekizgen kasnaklı bir kubbeyle örtülüdür.', 'The 11.95 × 11.86 m cooling room is covered by a dome on an octagonal drum, reached by squinches.', 'Cilt 1, s. 211', 2),
  (8, 'yap', 'Hediyelik dükkânlara göz at', 'Browse the gift shops', 'Kitaba göre iç mekân bugün ağırlıklı olarak antika ve turistik hediyelik eşya dükkânlarından oluşuyor.', 'According to the book, the interior now mainly holds shops selling antiques and souvenirs.', 'Cilt 1, s. 211', 3),
  (8, 'kesfet', 'UNESCO alanında dur', 'Stand in a UNESCO site', 'Hamamın içinde yer aldığı Hanlar Bölgesi, 2014''te UNESCO Dünya Mirası Alanı''na alınmıştır.', 'The Khans Area containing the bath joined the UNESCO World Heritage List in 2014.', 'Cilt 1, s. 213', 4),
  (9, 'kesfet', 'Bursa''nın Ayasofyası', 'Bursa''s Hagia Sophia', 'Evliya Çelebi, Ulucami''yi ''Bursa''nın Ayasofyası'' diye anar. Cami, Osmanlı''nın Bursa''daki ilk büyük camisidir.', 'Evliya Çelebi called the Grand Mosque ''the Hagia Sophia of Bursa''. It is the Ottomans'' first great mosque in Bursa.', 'Cilt 1, s. 37', 0),
  (9, 'gor', 'Minber kitabesini ara', 'Look for the minbar inscription', 'Minber kapısı üzerindeki ahşap oyma kitabe, yapının 1399-1400''de Yıldırım Bayezid tarafından tamamlandığını gösterir.', 'The carved wooden inscription above the minbar door shows it was completed by Bayezid I in 1399-1400.', 'Cilt 1, s. 41', 1),
  (9, 'kesfet', 'Çok kubbeli planı tanı', 'Recognise the multi-domed plan', 'Büyük Cuma camilerine Osmanlı kültüründe ''ulucami'' denir. Bursa Ulucami bu çok kubbeli planın örneğidir.', 'Great Friday mosques are called ''ulucami'' in Ottoman culture. The Bursa Grand Mosque is an example of this multi-domed plan.', 'Cilt 1, s. 39', 2),
  (9, 'kesfet', 'Somuncu Baba''nın izini sür', 'Follow Somuncu Baba''s trail', 'Açılışta bulunan Somuncu Baba, burada Fatiha suresinin yedi farklı düzeyde tefsirini yapmıştır.', 'Somuncu Baba attended the opening and gave a seven-level interpretation of the Fatiha here.', 'Cilt 1, s. 37', 3),
  (9, 'kesfet', 'Beşinci makam rivayetini oku', 'Read the ''fifth sanctuary'' tale', 'Halk arasında Ulucami, Mescid-i Haram, Mescid-i Nebevî, Mescid-i Aksâ ve Emeviyye Camii''nden sonra beşinci makam sayılır.', 'Tradition counts it as the fifth sanctuary after the Masjid al-Haram, the Prophet''s Mosque, Al-Aqsa and the Umayyad Mosque.', 'Cilt 1, s. 45', 4),
  (10, 'gor', 'Taç kapıya yakından bak', 'Study the portal', 'Yoğun taş oyma ve kabartma işlenen taç kapı için yaklaşık üç yıl çalışıldığı söylenir.', 'The portal, rich in stone carving and relief, is said to have taken about three years to make.', 'Cilt 2, s. 345', 0),
  (10, 'gor', 'Kitabeyi oku', 'Read the inscription', 'Taç kapıdaki celi sülüs üç satırlık kitabe, banisini ve 1419 tamamlanma tarihini kaydeder.', 'The three-line inscription on the portal records the patron and the completion in 1419.', 'Cilt 2, s. 345', 1),
  (10, 'gor', 'Pembe mermer cepheyi incele', 'Notice the pink marble', 'Dış cephe duvarları kesme taştır ve pembe mermer tabakalarla kaplanmıştır. Girişin iki yanında mermer mihrap nişleri vardır.', 'The outer walls are cut stone clad in pink marble. Marble mihrab niches flank the entrance.', 'Cilt 2, s. 351', 2),
  (10, 'kesfet', 'Altı kitabenin sırrı', 'Six inscriptions, six names', 'Bani, mimar, nakkaş başı, çini ve ahşap ustalarının adları altı ayrı kitabeyle kayda geçmiştir.', 'The patron, architect, chief painter, tile and wood masters are all named in six separate inscriptions.', 'Cilt 2, s. 339', 3),
  (10, 'kesfet', '''Yeşil'' adı nereden geliyor?', 'Why is it called ''Green''?', 'Yapıda kullanılan çinilerin rengi ve etkisi nedeniyle halk arasında ''Yeşil Cami'' denmiştir.', 'Because of the colour and effect of its tiles, people came to call it the ''Green Mosque''.', 'Cilt 2, s. 337', 4),
  (11, 'gor', 'Firuze çinilere bak', 'Admire the turquoise tiles', 'Sekiz cephenin tamamı firuze renkli çinilerle kaplıdır. Bu yüzden türbe Bursa''nın simgelerinden biri olmuştur.', 'All eight facades are covered in turquoise tiles, which made the tomb one of Bursa''s symbols.', 'Cilt 2, s. 391-393', 0),
  (11, 'kesfet', 'En yüksek Osmanlı türbesi', 'The tallest Ottoman tomb', 'Kubbesiyle birlikte 25,5 m yüksekliğe ulaşır. Osmanlı türbeleri arasında en yüksek örnektir.', 'With its dome it rises to 25.5 m, the tallest of all Ottoman tombs.', 'Cilt 2, s. 393', 1),
  (11, 'gor', 'Çini alınlıklardaki yazıları oku', 'Read the tile panels', 'Pencerelerin üstünde lacivert zemin üzerine beyaz sülüs hatla ayet ve hadisler yazılıdır.', 'Above the windows, verses and hadiths are written in white thuluth script on a dark blue ground.', 'Cilt 2, s. 393', 2),
  (11, 'kesfet', 'İkinci kurucunun hikâyesi', 'The ''second founder''', 'Çelebi Mehmed ''ikinci kurucu'' diye anılır. Ölüm haberi, devlet sarsılmasın diye kırk gün gizlenmiştir.', 'Çelebi Mehmed is called the ''second founder''. News of his death was hidden for forty days to keep the state stable.', 'Cilt 2, s. 391', 3),
  (11, 'gor', 'Cenazelik bölümünü bul', 'Find the ''cenazelik'' section', 'Doğu cephesindeki bu bölüm üç kol hâlinde beş gözlüdür. Tahnit edilmiş cenazeler için yapılmıştır.', 'This section on the east side has five bays in three arms and was made for embalmed bodies.', 'Cilt 2, s. 393', 4),
  (12, 'kesfet', 'Cami altta, medrese üstte', 'Mosque below, madrasa above', 'Medresenin caminin üst katında yer alması, Osmanlı mimarisinde ilk ve tek örnektir.', 'A madrasa placed on the upper floor of a mosque is a first and only case in Ottoman architecture.', 'Cilt 1, s. 85', 0),
  (12, 'gor', 'İki katlı revaklı avluya çık', 'Climb the two-storey arcade', '28,65 × 3,60 m''lik revaklı avlu iki katlıdır. Üst kat, Bursa ovasına bakan medrese avlusudur.', 'The 28.65 × 3.60 m arcaded court has two floors. The upper one is the madrasa court overlooking the Bursa plain.', 'Cilt 1, s. 89', 1),
  (12, 'gor', 'Ovaya bakan cepheyi incele', 'Study the façade over the plain', 'Kuzey cephe anıtsal biçimde düzenlenmiştir ve ovaya hâkimdir. Son cemaat yeri beş bölümlüdür.', 'The north façade is monumental and commands the plain. Its portico has five bays.', 'Cilt 1, s. 87', 2),
  (12, 'gor', 'Devşirme başlıkları ara', 'Hunt for reused capitals', 'Camide yapraklı Korint ve Kompozit sütun başlıkları devşirme malzeme olarak kullanılmıştır.', 'Leafy Corinthian and Composite capitals were reused as spolia in the mosque.', 'Cilt 1, s. 87', 3),
  (12, 'kesfet', 'Kaplıca İmareti adını öğren', 'Why ''Thermal Imaret''?', 'Çekirge, kaplıcalarıyla ünlü bir köydü. Bu yüzden külliyeye ''Kaplıca İmareti'' de denmiştir.', 'Çekirge was famed for its hot springs, so the complex was also called the ''Thermal Imaret''.', 'Cilt 1, s. 83', 4),
  (13, 'kesfet', 'Türkiye''deki tek çarşılı köprü', 'Turkey''s only bazaar bridge', 'Irgandı Köprüsü, Türkiye''de üzerinde çarşı bulunan tek köprüdür.', 'Irgandı Bridge is the only bridge in Turkey with a bazaar on it.', 'Cilt 2, s. 559', 0),
  (13, 'gor', 'Kemerin altına bak', 'Look under the arch', 'Köprü, 16 m açıklığında ve 11 m genişliğindeki bir kemerle Gökdere vadisinin iki yakasını birleştirir.', 'The bridge joins the two banks of the Gökdere valley with one arch 16 m wide and 11 m across.', 'Cilt 2, s. 559', 1),
  (13, 'gor', 'Dükkân sıralarını say', 'Count the shops', 'Her iki tarafta on altışar, toplam 32 dükkân ile bir mescit yer alır.', 'There are sixteen shops on each side, 32 in all, plus a small mosque.', 'Cilt 2, s. 563', 2),
  (13, 'kesfet', 'Avrupa''daki benzerlerini öğren', 'Meet its European cousins', 'Yapı, İtalya''daki Ponte Vecchio ve Ponte Rialto ile Bulgaristan''daki Osma köprüsüne benzer.', 'The bridge resembles Italy''s Ponte Vecchio and Ponte Rialto and Bulgaria''s Osma bridge.', 'Cilt 2, s. 559', 3),
  (13, 'kesfet', 'Yeniden ayağa kalkışı oku', 'Read about its rebuilding', '1922''de bombalanıp yaklaşık 27 yıl harabe kalan köprü, 1949''da onarılmaya başlandı.', 'Bombed in 1922, the bridge lay in ruins for about 27 years before repairs began in 1949.', 'Cilt 2, s. 563', 4),
  (14, 'kesfet', 'On üç türbeyi say', 'Count the thirteen tombs', 'Külliyedeki on üç türbeden ilki 1442''de, sonuncusu 1573''te yapıldı. Tanpınar buraya ''sabrın acı meyvesi'' demiştir.', 'Of the thirteen tombs, the first dates from 1442 and the last from 1573. Tanpınar called it ''the bitter fruit of patience''.', 'Cilt 1, s. 115', 0),
  (14, 'kesfet', 'Rekor sürede tamamlandı', 'Built in record time', 'Külliye 1425''te başlayıp 1426''da bitmiştir. Osmanlı''nın en kısa sürede tamamlanan sultan külliyelerinden biridir.', 'Begun in 1425 and finished in 1426, it is among the fastest sultanic complexes the Ottomans completed.', 'Cilt 1, s. 117', 1),
  (14, 'gor', 'İnşa kitabesini bul', 'Find the building inscription', 'İnşa kitabesi caminin ana giriş kapısının üzerindedir.', 'The foundation inscription sits above the mosque''s main entrance door.', 'Cilt 1, s. 117', 2),
  (14, 'kesfet', 'Simaviler Mahallesi''ni düşün', 'Think of the Simaviler quarter', 'Külliye genellikle gayrimüslimlerin yaşadığı bir mahallede kuruldu. Bu, Osmanlı''nın sosyal hizmette din ayrımı gözetmediğini gösterir.', 'The complex was founded in a quarter mostly home to non-Muslims, showing that Ottoman social service made no distinction of faith.', 'Cilt 1, s. 117', 3),
  (15, 'kesfet', 'Tepedeki külliyeyi tanı', 'Meet the hilltop complex', 'Şehre hâkim bir tepedeki külliye; cami, zaviye, imaret, türbe, hamam, mektep, muvakkithane, çeşme ve kütüphaneden oluşur.', 'On a hill above the city, the complex includes a mosque, lodge, soup kitchen, tomb, bath, school, timekeeper''s room, fountain and library.', 'Cilt 2, s. 273', 0),
  (15, 'kesfet', 'Emîr Sultan kimdir?', 'Who was Emîr Sultan?', '1368''de Buhara''da doğan Emîr Sultan, hacdan dönüşünde Bursa''ya yerleşmiş önemli bir mutasavvıftır.', 'Born in Bukhara in 1368, Emîr Sultan was a leading Sufi who settled in Bursa after the pilgrimage.', 'Cilt 2, s. 275', 1),
  (15, 'kesfet', 'Caminin iki rivayetini oku', 'Read two tales of the mosque', 'Bir rivayete göre cami, Emîr Sultan''a minnettar bir tüccar tarafından yaptırıldı. Kıble yönüne sonradan iki kubbe eklendi.', 'One tale says a grateful merchant built the mosque for Emîr Sultan. Two domes were later added on the qibla side.', 'Cilt 2, s. 275', 2),
  (15, 'kesfet', 'Eklerle büyüyen yapıyı izle', 'See how it grew', 'Külliye, ilk yapıdan sonra farklı dönemlerde farklı kişilerin eklemeleriyle genişlemiştir.', 'After the first building, the complex grew through additions made by different people in different periods.', 'Cilt 2, s. 273', 3),
  (16, 'kesfet', '''Yeşil'' adının nedeni', 'Why ''Green''?', 'Çinilerin rengi ve estetik etkisi nedeniyle külliye halk arasında ''Yeşil Cami Külliyesi'' diye anılır.', 'Because of its tiles'' colour and beauty, the complex is known as the ''Green Mosque Complex''.', 'Cilt 2, s. 337', 0),
  (16, 'kesfet', 'Çok renkli sırın ilk durağı', 'First multicolour glaze', 'Osmanlı mimarisinde çok renkli sır altı tekniğinin ilk kez uygulandığı yapı topluluğudur.', 'It is the first Ottoman complex to use multicolour underglaze tilework.', 'Cilt 2, s. 337', 1),
  (16, 'kesfet', 'Külliyenin birimlerini say', 'List the complex''s parts', 'Külliye cami, türbe, medrese, imaret, han, hamam ve çarşıdan oluşur. 1414''te başlayıp 1419''da tamamlanmıştır.', 'The complex has a mosque, tomb, madrasa, soup kitchen, han, bath and bazaar. Begun in 1414, it was finished in 1419.', 'Cilt 2, s. 337', 2),
  (16, 'kesfet', 'Vakfiyeyi öğren', 'Learn about the endowment deed', '259 satırlık vakfiye 1419 tarihlidir. Osmanlı''nın vakıf sistemi ve şehircilik anlayışını gösteren bir belgedir.', 'The 259-line endowment deed dates from 1419 and shows the Ottoman waqf system and approach to urban planning.', 'Cilt 2, s. 341', 3),
  (17, 'kesfet', 'Bursa''daki son sultan camii', 'Bursa''s last sultanic mosque', 'Muradiye Camii, Bursa''daki sultan camilerinin sonuncusudur ve zaviyeli (tabhaneli) plan şemasıyla yapılmıştır.', 'Muradiye is the last of Bursa''s sultanic mosques, built on the lodge (tabhane) plan.', 'Cilt 1, s. 119', 0),
  (17, 'gor', 'Giriş kitabesini oku', 'Read the entrance inscription', 'Ana giriş kapısı üzerindeki kitabe, yapımın 1425''te başlayıp 1426''da bittiğini belgeler.', 'The inscription over the main door records that building began in 1425 and ended in 1426.', 'Cilt 1, s. 117', 1),
  (17, 'gor', 'Mukarnaslı kubbeye bak', 'Look up at the muqarnas dome', 'Orta giriş bölümü, tamamen mukarnas dolgulu ve mukarnas tromplu bir kubbeyle örtülüdür.', 'The central entrance bay is covered by a dome fully filled with muqarnas and set on muqarnas squinches.', 'Cilt 1, s. 119', 2),
  (17, 'gor', 'Tuğla desenlerini say', 'Spot the brick patterns', 'Son cemaat yerinin revak cephesi, on beş değişik geometrik düzende örülmüş tuğlalarla hareketlendirilmiştir.', 'The portico façade is animated by bricks laid in fifteen different geometric patterns.', 'Cilt 1, s. 119', 3),
  (17, 'gor', 'Yeşil çinileri ara', 'Find the green tiles', 'Zümrüt yeşili çiniler daha önce Yeşil Cami''de de kullanılmıştır. Bu, aynı Tebrizli usta grubunun burada da çalıştığını gösterir.', 'The emerald-green tiles were already used at the Green Mosque, showing the same Tabriz masters worked here.', 'Cilt 1, s. 121', 4),
  (18, 'gor', 'Sekizgen havuzu bul', 'Find the octagonal pool', '17 × 17 m''lik revaklı avlunun ortasında mermerden sekizgen bir havuz yer alır.', 'A marble octagonal pool stands in the middle of the 17 × 17 m arcaded courtyard.', 'Cilt 1, s. 125', 0),
  (18, 'gor', 'On altı hücreyi say', 'Count the sixteen cells', 'Tek eyvanlı medresede öğrenci hücrelerinin önünde kubbeli ve tonozlu revaklar uzanır.', 'Domed and vaulted arcades run in front of the student cells of this single-iwan madrasa.', 'Cilt 1, s. 125', 1),
  (18, 'gor', 'Çini panolu dershaneye gir', 'Enter the tiled lecture hall', 'Dershane eyvanının duvarları çini panolarla, diğer yüzeyleri geometrik tuğla işçiliğiyle süslüdür.', 'The lecture iwan''s walls are decorated with tile panels and its other surfaces with geometric brickwork.', 'Cilt 1, s. 127', 2),
  (18, 'gor', 'Taç kapıya bak', 'Look at the portal', 'Kuzey cephedeki taç kapı, mukarnaslı tromplu bir kubbeyle örtülü sivri kemerli bir eyvandır.', 'The north portal is a pointed-arch iwan covered by a dome on muqarnas squinches.', 'Cilt 1, s. 125', 3),
  (18, 'kesfet', 'Medreseden müzeye', 'From madrasa to museum', 'Medrese 1951''de dispanser oldu, 2005-2010 arasında Bursa sağlık tarihi müzesi olarak kullanıldı.', 'The madrasa became a clinic in 1951 and from 2005 to 2010 served as a museum of Bursa''s medical history.', 'Cilt 1, s. 127', 4),
  (19, 'kesfet', 'Sandukasız padişah mezarı', 'A sultan''s grave without a sarcophagus', 'Bursa''da sanduka veya lahit kullanılmayan tek padişah mezarıdır.', 'It is the only sultan''s tomb in Bursa without a sarcophagus.', 'Cilt 1, s. 135', 0),
  (19, 'kesfet', 'Vasiyetine sadık kalındı', 'His will was honoured', 'II. Murad, mezarın Peygamber''in sünnetine uygun olmasını istedi. Kripta yapılmadı, naaşı doğrudan toprağa defnedildi.', 'Murad II asked for a tomb following the Prophet''s practice. No crypt was built and he was buried directly in the earth.', 'Cilt 1, s. 135', 1),
  (19, 'gor', 'Üstü açık kubbeyi gör', 'See the open roof', 'Oğlu II. Mehmed''in yaptırdığı türbe kare planlı, üstü açık ve dört yönden sofalıdır.', 'Built by his son Mehmed II, the tomb is square, open to the sky and has porches on four sides.', 'Cilt 1, s. 135', 2),
  (19, 'gor', 'Kapı kitabesine bak', 'Look at the door inscription', 'Kapı üzerindeki üç satırlık celi sülüs kitabe, 1451 tarihlidir.', 'The three-line thuluth inscription above the door is dated 1451.', 'Cilt 1, s. 135-137', 3),
  (20, 'gor', 'Çinili duvarları incele', 'Study the tiled walls', 'Duvarlar 2,35 m yüksekliğe kadar firuze ve lacivert altıgen çinilerle kaplıdır. Muradiye türbeleri arasında en zengin süslemeye sahiptir.', 'The walls are tiled in turquoise and dark blue hexagons up to 2.35 m. It has the richest decoration of the Muradiye tombs.', 'Cilt 1, s. 149', 0),
  (20, 'gor', 'Kubbenin içine bak', 'Look into the dome', 'Kubbe içi rumi ve hatâyî motifleriyle doludur. Eteğinde altı kartuşta Âyetü''l-kürsî yazılıdır.', 'The dome interior is filled with rumi and hatayi motifs, and Ayat al-Kursi runs around its base in six cartouches.', 'Cilt 1, s. 149', 1),
  (20, 'gor', 'Servi motiflerini bul', 'Find the cypress motifs', 'Kalem işi süslemelerde servi motifleri malakâri tekniğiyle işlenmiştir.', 'Among the painted decoration, cypress motifs are worked in the malakari technique.', 'Cilt 1, s. 149', 2),
  (20, 'kesfet', 'Cem Sultan''ın yolculuğu', 'Cem Sultan''s journey', 'Napoli''de vefat eden Cem Sultan''ın cenazesi 1499''da Bursa''ya getirilip bu türbeye defnedildi. Türbe bu yüzden onun adıyla anılır.', 'Cem Sultan died in Naples and his body was brought to Bursa in 1499. The tomb is named after him.', 'Cilt 1, s. 145', 3),
  (20, 'gor', 'On altı pencereyi say', 'Count the sixteen windows', 'Altıgen planlı türbe, alt sırada dört, üst sırada altı ve kasnakta altı olmak üzere on altı pencereyle aydınlanır.', 'The hexagonal tomb is lit by sixteen windows: four below, six above and six in the drum.', 'Cilt 1, s. 149', 4),
  (21, 'kesfet', 'Hatun''un hayırseverliği', 'A patron''s good works', 'Şirin Hatun; Trabzon''da bir mescit, Bursa ve Mihaliç''te birer mektep yaptırıp bunlar için vakıf kurmuştur.', 'Şirin Hatun built a mosque in Trabzon and schools in Bursa and Mihaliç, and endowed foundations for them.', 'Cilt 1, s. 171', 0),
  (21, 'gor', 'Üç sandukayı bul', 'Find the three sarcophagi', 'Türbede Şirin Hatun, Ferahşah Hatun ve Aynışah Sultan''a ait üç sanduka bulunur.', 'The tomb holds three sarcophagi: Şirin Hatun, Ferahşah Hatun and Aynışah Sultan.', 'Cilt 1, s. 171', 1),
  (21, 'gor', 'Kubbenin kalem işlerine bak', 'Study the dome''s painting', '2013 restorasyonunda 19. yüzyıl Barok süslemeler kaldırıldı, 16. yüzyıla ait özgün motifler ortaya çıktı.', 'In the 2013 restoration the 19th-century Baroque additions were removed, revealing original 16th-century motifs.', 'Cilt 1, s. 171', 2),
  (21, 'gor', 'Âyetü''l-kürsî kuşağını oku', 'Read the inscription band', 'Batı duvarındaki kuşakta, sülyen zemin üzerine beyaz sülüs hatla Âyetü''l-kürsî yazılıdır.', 'On the west wall a band shows Ayat al-Kursi in white thuluth script on a red-lead ground.', 'Cilt 1, s. 173', 3),
  (21, 'gor', 'Sekizgen kasnağa bak', 'Look at the octagonal drum', 'Kare planlı türbe, yüksek sekizgen kasnağa oturan tromplu bir kubbeyle örtülüdür.', 'The square tomb is covered by a dome on squinches, rising from a tall octagonal drum.', 'Cilt 1, s. 171', 4),
  (22, 'kesfet', 'Herkese açık sofra', 'A table for everyone', 'Vakfiyeye göre imarette günde iki öğün yemek pişirilir ve zengin fakir ayrımı yapılmadan halka sunulurdu.', 'According to the endowment deed, two meals a day were cooked and served to all, rich or poor alike.', 'Cilt 2, s. 375', 0),
  (22, 'gor', 'Mutfak ve yemek salonunu ayırt et', 'Tell kitchen from dining hall', 'Yapı art arda iki bölümdür: 26 × 10 m''lik mutfak ve 16,30 × 10 m''lik yemek salonu.', 'The building has two sections in a row: a 26 × 10 m kitchen and a 16.30 × 10 m dining hall.', 'Cilt 2, s. 373', 1),
  (22, 'gor', 'Çift kubbeye bak', 'Look at the double dome', 'Matbah kısmı, dışarıdan kiremit kaplı çift kubbesiyle dikkat çeker.', 'The kitchen section stands out from outside with its tile-covered double dome.', 'Cilt 2, s. 373', 2),
  (22, 'kesfet', 'Yedi fırını say', 'Count the seven ovens', 'İmarethanede toplam yedi fırın bulunur.', 'The soup kitchen has seven ovens in total.', 'Cilt 2, s. 375', 3),
  (22, 'kesfet', 'Sultanın Cuma sofrası', 'The sultan''s Friday meal', 'Kaynaklarda Çelebi Mehmed''in Cuma günleri bizzat yemek dağıttığına dair rivayetler vardır.', 'Sources hold tales that Çelebi Mehmed served meals himself on Fridays.', 'Cilt 2, s. 375', 4),
  (23, 'kesfet', 'İlk medreselerden biri', 'One of the earliest madrasas', 'Sultaniye Medresesi, Osmanlı eğitim kurumlarının ilk örneklerinden biridir.', 'The Sultaniye Madrasa is one of the first examples of Ottoman educational institutions.', 'Cilt 2, s. 377', 0),
  (23, 'gor', 'Üç eyvanlı planı gör', 'See the three-iwan plan', '36 × 38,50 m ölçülerindeki medrese, üç eyvanlı şemasıyla Selçuklu açık avlulu medreselerinin devamıdır.', 'The 36 × 38.5 m madrasa continues the Seljuk open-court tradition with its three-iwan plan.', 'Cilt 2, s. 379', 1),
  (23, 'gor', 'Müderris odasını ara', 'Look for the professor''s room', 'Revaklara açılan 13 odanın biri müderris odasıdır.', 'Of the 13 rooms opening onto the arcades, one is the professor''s room.', 'Cilt 2, s. 379', 2),
  (23, 'kesfet', 'Öğrencilerin günlüğü', 'A student''s daily allowance', 'Vakfiyeye göre otuz öğrencinin her birine günde bir dirhem ücret verilir ve zaviyeden iki öğün yemek sağlanırdı.', 'The deed provided each of thirty students one dirham a day and two meals from the lodge.', 'Cilt 2, s. 377', 3),
  (23, 'kesfet', 'Gelirini hanlar sağlıyordu', 'Funded by hans', 'Medresenin giderleri İpek Han ve Geyve Han gibi gelir getiren yapılara bağlanmıştı.', 'The madrasa''s costs were met by income-producing buildings such as İpek Han and Geyve Han.', 'Cilt 2, s. 377', 4);
